example_item.example_item_data:
filename = [tempname(), '.nh5'];
m = nh5file(filename)
m.savedVar(81:100, 81:100) = magic(20);
[nrows, ncols] = size(m, 'savedVar')
loadVar = m.savedVar(nrows - 19:nrows, 86:95)

filename = [tempname(), '.nh5'];
stocks = rand(1000, 4);
savenh5(filename, 'stocks');
m = nh5file(filename);
[nrows, ncols] = size(m, 'stocks');
avgs = zeros(1, ncols);
for k = 1:ncols
  avgs(k) = mean(m.stocks(:, k));
end
avgs

filename = [tempname(), '.nh5'];
x = magic(4);
savenh5(filename, 'x');
m = nh5file(filename);
m.Properties.Writable = true;
m.x(2, :) = [0 0 0 0];
m.y = 'new variable';
whos(m)
